Rules.InvariantScript:
ClearCollect(
    colMyRequests,
    SortByColumns(
        Filter('Vacations Tracking (Days)', Employee = User().Email),
        "StartDate",
        SortOrder.Descending
    )
);
Set(varShowSubmitSheet, false);
Set(varShowDeleteConfirm, false);

Text(
    Sum(
        Filter(
            colMyRequests,
            Year(StartDate) = Year(Today()) &&
            ApprovalStatus_1 <> "Rejected"
        ),
        Days
    )
)

Set(varDeleteRequestID, ThisItem.ID);
Set(varDeleteRequestLog, ThisItem.LOG_ID);
Set(varDeleteStart, ThisItem.StartDate);
Set(varDeleteEnd, ThisItem.EndDate);
Set(varShowDeleteConfirm, true);

With(
    {
        varStart: StartDatePicker_Date.SelectedDate,
        varEnd: EndDatePicker_Date.SelectedDate,
        varDiff: DateDiff(StartDatePicker_Date.SelectedDate, EndDatePicker_Date.SelectedDate) + 1
    },
    If(
        Or(IsBlank(varStart), IsBlank(varEnd), varDiff <= 0, varDiff > 50000),
        0,
        If(
            StartDatePicker_Date.SelectedDate = EndDatePicker_Date.SelectedDate && dd_LeaveTime.Selected.Value <> "Full Day",
            0.5,
            With(
                {
                    varDateRange: ForAll(Sequence(varDiff), varStart + Value - 1)
                },
                CountIf(
                    varDateRange,
                    And(
                        Weekday(Value) in [2, 3, 4, 5, 6],
                        Not(Value in ForAll(colPublic_Holidays, DateValue(CleanDate)))
                    )
                )
            )
        )
    )
)

If(
    varIsSaving,
    Notify("Please wait...", NotificationType.Warning),
    IsBlank(StartDatePicker_Date.SelectedDate) || IsBlank(EndDatePicker_Date.SelectedDate),
    Notify("Select start and end dates", NotificationType.Warning),
    EndDatePicker_Date.SelectedDate < StartDatePicker_Date.SelectedDate,
    Notify("End date must be on or after start date", NotificationType.Warning),
    Year(StartDatePicker_Date.SelectedDate) <> Year(EndDatePicker_Date.SelectedDate),
    Notify("Leave must be within a single year", NotificationType.Warning),
    Value(lbl_DaysCalc.Text) <= 0,
    Notify("No working days in this range", NotificationType.Warning),
    IsBlank(varApproverEmail),
    Notify("No approver assigned in Employees list", NotificationType.Error),
    IsBlank(dd_LeaveType.Selected.Value),
    Notify("Select a leave type", NotificationType.Warning),
    CountRows(
        Filter(
            colMyRequests,
            ApprovalStatus_1 <> "Rejected" &&
            StartDate <= EndDatePicker_Date.SelectedDate &&
            EndDate >= StartDatePicker_Date.SelectedDate
        )
    ) > 0,
    Notify("Overlaps an existing leave request", NotificationType.Error),
    Set(varIsSaving, true);
    Set(GUID_Var, GUID());
    With(
        {
            varStart: StartDatePicker_Date.SelectedDate,
            varEnd: EndDatePicker_Date.SelectedDate,
            varDiff: DateDiff(StartDatePicker_Date.SelectedDate, EndDatePicker_Date.SelectedDate) + 1
        },
        ClearCollect(
            colLeaveDates,
            ForAll(
                Filter(
                    ForAll(Sequence(varDiff), { LeaveDate: varStart + Value - 1 }),
                    Weekday(LeaveDate) in [2, 3, 4, 5, 6] &&
                    Not(LeaveDate in ForAll(colPublic_Holidays, DateValue(CleanDate)))
                ),
                { LeaveDate: LeaveDate }
            )
        )
    );
    ClearCollect(
        colHoursSync,
        Filter(
            'Hours Tracking (Hours)',
            Employee = User().Email &&
            Date >= StartDatePicker_Date.SelectedDate &&
            Date <= EndDatePicker_Date.SelectedDate
        )
    );
    If(
        CountRows(
            Filter(
                colHoursSync,
                Date in ForAll(colLeaveDates, LeaveDate) &&
                (Task = "Work Day" || Task = "Weekend" || IsBlank(Task)) &&
                Coalesce(Standard_time, 0) > 0
            )
        ) > 0,
        Set(varIsSaving, false);
        Notify("Staff Club already has worked hours on a day in this range. Clear those hours first.", NotificationType.Error),
        Patch(
            'Vacations Tracking (Days)',
            Defaults('Vacations Tracking (Days)'),
            {
                Title: GUID_Var,
                LOG_ID: GUID_Var,
                Employee: User().Email,
                Employee_Name: User().FullName,
                Project: Selected_ProjectID,
                StartDate: StartDatePicker_Date.SelectedDate,
                EndDate: EndDatePicker_Date.SelectedDate,
                Days: Value(lbl_DaysCalc.Text),
                Leave_Time: If(
                    StartDatePicker_Date.SelectedDate = EndDatePicker_Date.SelectedDate,
                    dd_LeaveTime.Selected.Value,
                    "Full Day"
                ),
                Type_of_leave: dd_LeaveType.Selected.Value,
                Comments: txt_Comments.Text,
                App_Name: "Dayaway_HR_Vacations",
                ApproverID_1: varApproverEmail,
                ApprovalStatus_1: "Pending"
            }
        );
        ForAll(
            colLeaveDates As d,
            With(
                {
                    dayLog: GUID_Var & "_" & Text(d.LeaveDate, "yyyymmdd")
                },
                Patch(
                    'Hours Tracking (Hours)',
                    Defaults('Hours Tracking (Hours)'),
                    {
                        Title: dayLog,
                        LOG_ID: dayLog,
                        Employee: User().Email,
                        Employee_Name: User().FullName,
                        Date: d.LeaveDate,
                        Task: dd_LeaveType.Selected.Value,
                        Standard_time: 0,
                        Comments: txt_Comments.Text,
                        App_Name: "Dayaway",
                        ApproverID_1: varApproverEmail,
                        ApprovalStatus_1: "Pending"
                    }
                )
            )
        );
        Office365Outlook.SendEmailV2(
            varApproverEmail,
            dd_LeaveType.Selected.Value & " Request Submitted",
            "A new " & dd_LeaveType.Selected.Value & " request has been submitted by " & User().FullName &
            ". Please review in DayAway.<br><br>" &
            "<b>Type:</b> " & dd_LeaveType.Selected.Value & "<br>" &
            "<b>Dates:</b> " & Text(StartDatePicker_Date.SelectedDate, "dd-mmm-yyyy") &
            " to " & Text(EndDatePicker_Date.SelectedDate, "dd-mmm-yyyy") & "<br>" &
            "<b>Comments:</b> " & txt_Comments.Text,
            { IsHtml: true }
        );
        Notify("Leave submitted", NotificationType.Success);
        Reset(dd_LeaveType);
        Reset(dd_LeaveTime);
        Reset(txt_Comments);
        Set(varShowSubmitSheet, false);
        ClearCollect(
            colMyRequests,
            SortByColumns(
                Filter('Vacations Tracking (Days)', Employee = User().Email),
                "StartDate",
                SortOrder.Descending
            )
        );
        Set(varIsSaving, false)
    )
)

Remove(
    'Vacations Tracking (Days)',
    LookUp('Vacations Tracking (Days)', ID = varDeleteRequestID)
);
ClearCollect(
    colHoursSync,
    Filter(
        'Hours Tracking (Hours)',
        Employee = User().Email &&
        Date >= varDeleteStart &&
        Date <= varDeleteEnd
    )
);
ClearCollect(
    colHoursSync,
    Filter(
        colHoursSync,
        StartsWith(LOG_ID, varDeleteRequestLog & "_")
    )
);
ForAll(
    colHoursSync As h,
    Remove(
        'Hours Tracking (Hours)',
        LookUp('Hours Tracking (Hours)', ID = h.ID)
    )
);
Set(varShowDeleteConfirm, false);
Notify("Request deleted", NotificationType.Success);
ClearCollect(
    colMyRequests,
    SortByColumns(
        Filter('Vacations Tracking (Days)', Employee = User().Email),
        "StartDate",
        SortOrder.Descending
    )
);
